class Solution {
public:
    int minimumOperations(vector<int>& nums) {
        bool seen[101] = {};
        int count = 0;
        for (int x : nums) {
            if (x > 0 && !seen[x]) {
                seen[x] = true;
                count++;
            }
        }
        return count;
    }
};
